-- Run this once in the Supabase SQL editor.
-- Creates the lecture tables. Existing course rows are kept.

begin;

create table if not exists "Courses" (
    "Id" integer generated by default as identity primary key,
    "Code" text not null,
    "Name" text not null,
    "Description" text not null
);

create table if not exists "Lectures" (
    "Id" integer generated by default as identity primary key,
    "CourseId" integer not null references "Courses"("Id") on delete cascade,
    "Title" text not null,
    "ProfessorName" text not null,
    "OriginalFileName" text not null,
    "OriginalObjectName" text not null,
    "Stage" text not null,
    "Detail" text,
    "CreatedAt" timestamptz not null
);

create table if not exists "LectureRenditions" (
    "Id" integer generated by default as identity primary key,
    "LectureId" integer not null references "Lectures"("Id") on delete cascade,
    "Label" text not null,
    "Format" text not null,
    "Height" integer not null,
    "ObjectName" text not null,
    "PlaybackUrl" text not null
);

insert into "Courses" ("Code", "Name", "Description")
select
    'CC101',
    'Cloud Computing',
    'Ligjërata online për ruajtjen, përpunimin dhe shpërndarjen e videove në cloud.'
where not exists (select 1 from "Courses");

commit;
